import{c as t,Q as n,j as a,m as r}from"./chunks/framework.BqPkuuVc.js";const c=JSON.parse('{"title":"Seeding from the IOF world ranking","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/iof-ranking.md","filePath":"user/event-setup/iof-ranking.md"}'),o={name:"user/event-setup/iof-ranking.md"};function s(i,e,l,h,d,g){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="seeding-from-the-iof-world-ranking" tabindex="-1">Seeding from the IOF world ranking <a class="header-anchor" href="#seeding-from-the-iof-world-ranking" aria-label="Permalink to &quot;Seeding from the IOF world ranking&quot;">​</a></h1><p><strong>Audience:</strong> Organisers seeding a start draw for an event with elite or international entrants.</p><p>How to download the IOF world ranking and write each entrant&#39;s world place onto them as their ranking, ready for a draw by ranking.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p><strong>Seed from IOF ranking</strong> downloads the current world ranking from ranking.orienteering.org and gives every entrant who&#39;s on it their world place as their <strong>Ranking</strong>. A <a href="./start-draw#drawing-by-ranking">draw by ranking</a> then seeds them in that order. It works across several events at once, such as the days of a carnival.</p><ul><li><strong>Competitors are matched on their IOF ID, and nothing else.</strong> The list is every ranked athlete in the world, so a match on name would sooner or later give a club runner somebody else&#39;s place. Only entrants who carry an IOF ID can be seeded. For any other list — a national ranking, a squad&#39;s order — matched by ID, card or name, <a href="./import-event-data#importing-rankings">import it as a file</a>.</li><li><strong>A ranking you already have is kept unless you say otherwise.</strong> Most of a field isn&#39;t on the world ranking, and someone not on it isn&#39;t thereby unranked: their place may have come from a national list. Clearing one is something you tick, row by row.</li><li><strong>Nothing is written until you click Apply</strong>, and you see every row first.</li></ul><p>Open it from <strong>Competitors → Actions → Seed from IOF ranking…</strong> for this event, or from the <strong>Events</strong> list under <strong>Multi-event → Seed from IOF ranking…</strong> for several.</p><h2 id="before-you-start-iof-ids" tabindex="-1">Before you start: IOF IDs <a class="header-anchor" href="#before-you-start-iof-ids" aria-label="Permalink to &quot;Before you start: IOF IDs&quot;">​</a></h2><p>The world ranking can only reach entrants who have an <strong>IOF ID</strong>, and entries often arrive without one: the entry list downloaded from the Eventor website carries Eventor&#39;s own IDs, not IOF IDs. Fill them in first. See <a href="./import-event-data#importing-iof-ids">Importing IOF IDs</a>.</p><h2 id="step-1-the-events" tabindex="-1">Step 1: the events <a class="header-anchor" href="#step-1-the-events" aria-label="Permalink to &quot;Step 1: the events&quot;">​</a></h2><p>Opened from the <strong>Events</strong> list, the first step asks <strong>Which events should be seeded?</strong> Tick each one.</p><p>Events dated before today aren&#39;t listed, apart from the one you opened it from and the other days of its carnival. An event that <strong>Has run</strong> is marked: you can still seed it, though a ranking only matters to a draw that hasn&#39;t been made.</p><p>Opened from one event&#39;s Competitors page, this step is skipped.</p><h2 id="step-2-the-list-and-the-rows" tabindex="-1">Step 2: the list and the rows <a class="header-anchor" href="#step-2-the-list-and-the-rows" aria-label="Permalink to &quot;Step 2: the list and the rows&quot;">​</a></h2><p><strong>List</strong> chooses which world ranking to use:</p><ul><li><strong>Foot — middle and long</strong></li><li><strong>Foot — sprint</strong></li><li><strong>Mountain bike</strong></li><li><strong>Ski</strong></li><li><strong>Trail</strong></li></ul><p>Each covers men and women together. There are no junior or age-class lists; for one of those, <a href="./import-event-data#importing-rankings">import a ranking list</a> instead.</p><p>Manager downloads the list and keeps it for a day, so opening it again is instant. The line under <strong>List</strong> says when it was downloaded and how many athletes it holds. Click <strong>Refresh</strong> to download it again now.</p><p>Then the table: one row per entrant who carries an IOF ID, with their <strong>Name</strong>, <strong>Class</strong>, <strong>Event</strong> (when there&#39;s more than one), <strong>Country</strong>, the ranking they have <strong>Now</strong>, and the <strong>Ranking</strong> they&#39;ll get.</p><p>Above it, two counts:</p><ul><li><strong>How many have no IOF ID</strong>, and so can&#39;t be matched. At a club event that&#39;s most of the field: don&#39;t read a short table as a failed download. If <em>nobody</em> in the events carries one, Manager says so instead of showing a table — fill the IOF IDs in first.</li><li><strong>How many hold a place the world list doesn&#39;t have.</strong> Their rows are listed but <strong>not ticked</strong>. Tick one to clear that place; its <strong>Ranking</strong> cell is blank, because that&#39;s what it will be.</li></ul><p>Someone whose ranking is already their world place isn&#39;t listed as a change, and can&#39;t be ticked.</p><p>The rows that would change are ticked to begin with, and the title bar counts how many are ticked. Leave ticked the rows you want, then click <strong>Apply</strong>. Manager lists what it wrote, and anything it couldn&#39;t write, to put on by hand.</p><h2 id="without-internet" tabindex="-1">Without internet <a class="header-anchor" href="#without-internet" aria-label="Permalink to &quot;Without internet&quot;">​</a></h2><p>The download needs the internet on the computer running Manager. Without it, Manager uses the list it downloaded last, says so above the table, and carries on. So <strong>download the list before you leave for the venue</strong>: open the dialog once at home, or click <strong>Refresh</strong>, and the copy is kept.</p><p>If a download fails, the copy you already had is kept, never replaced by an empty or partial one, and Manager says which kind of failure it was:</p><ul><li><strong>The world ranking could not be downloaded.</strong> Usually no connection. It works again once there is one.</li><li><strong>…answered with something that is not a ranking list.</strong> The ranking site has changed, and this won&#39;t fix itself: report it.</li><li><strong>Only one of the two world ranking lists could be downloaded.</strong> The men&#39;s and women&#39;s lists are downloaded separately; with only one, neither is used. Try <strong>Refresh</strong> again.</li></ul><p>Separately, if some rows of a downloaded list couldn&#39;t be read, Manager says how many, so you know athletes may be missing from the table.</p><h2 id="after-seeding" tabindex="-1">After seeding <a class="header-anchor" href="#after-seeding" aria-label="Permalink to &quot;After seeding&quot;">​</a></h2><ul><li><strong>Check the result</strong> on the Competitors page: turn on the <strong>Ranking</strong> column and sort by it. See <a href="./competitors-clubs-teams#ranking">Ranking</a>.</li><li><strong>Draw the start list</strong> with <strong>By ranking</strong>. See <a href="./start-draw#drawing-by-ranking">Drawing by ranking</a>.</li><li>Seeding again later, after the ranking is republished, changes only the places that moved.</li></ul><p>Every place written is in the <a href="./../reference/audit-trail">audit trail</a> with the source <strong>IOF ranking</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./competitors-clubs-teams#ranking">Competitors, clubs and teams: Ranking</a></li><li><a href="./start-draw">Drawing start times</a></li><li><a href="./import-event-data">Importing event data</a></li><li><a href="./bib-numbers">Bib numbers</a></li><li><a href="./multi-stage-events">Multi-stage events</a></li></ul>',33)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
